import { useState } from "react";

/* ============================================================
   工事写真台帳（施工管理版）v5 — 職人路線リデザイン試作
   構成：1ページに測定箇所3箇所（別部位・各1枚）。縦に3段。
   変更：写真エリアと情報欄の横幅を黄金比（約1.618:1）で配分。
        写真＝約62%（黄金比の大）、情報欄＝約38%（黄金比の小）。
   ・写真は iPhone 横向き（4:3 横長）想定。黄金比の幅の中で 4:3 を表示。
   ・工程名は nowrap で1行に収め、改行を解消。
   ・合否判定なし（基準値・実測値を事実として並べる）。
   方向性：崩した中の真面目さ／職人・力強さ（施工前後報告書と世界観統一）
   ※ デモ。実測値は見本値、写真はプレースホルダ。
   ============================================================ */

const C = {
  ink: "#1c1f22", steel: "#2f363d", ainezu: "#4a5560",
  kawara: "#6b7178", rust: "#c0492f", moss: "#5a7d52",
  paper: "#f7f5f1", line: "#d8d4cc",
};

// 黄金比 φ ≒ 1.618 → 写真:情報 = 1.618:1 = 61.8% : 38.2%
const PHOTO_W = "61.8%";
const INFO_W = "38.2%";

const REAL_PHOTO = "data:image/jpeg;base64,";

const ROWS = [
  {
    no: 1, date: "2026/06/30", place: "北棟 東流れ",
    work: "屋根防水シート・防水テープ 搬入確認",
    standard: 200, actual: 200, unit: "mm", rule: "規格",
    photo: REAL_PHOTO,
    note: "田島ルーフィング 防水テープS（200mm×20m・4巻入）を確認。",
  },
  {
    no: 2, date: "2026/06/30", place: "北棟 軒先",
    work: "ルーフィング重ね幅確認（ヨコ）",
    standard: 250, actual: 260, unit: "mm", rule: "以上",
    note: "左右の重ねを実測して記録。",
  },
  {
    no: 3, date: "2026/06/30", place: "南棟 谷部",
    work: "防水ルーフィング施工",
    standard: 200, actual: 210, unit: "mm", rule: "以上",
    note: "谷部の増し張り範囲と重ねを確認。",
  },
];

export default function KobetsuLedgerV5() {
  const [n, setN] = useState(3);
  const rows = ROWS.slice(0, n);

  return (
    <div style={{ background: C.steel, minHeight: "100vh", padding: "0 0 50px",
      fontFamily: '"Hiragino Sans","Hiragino Kaku Gothic ProN",-apple-system,sans-serif' }}>
      <style>{`*{box-sizing:border-box}button{font-family:inherit;cursor:pointer}
        @media print{.no-print{display:none!important}body{background:#fff!important}
        .sheet{box-shadow:none!important;margin:0!important}
        *{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}}`}</style>

      <div className="no-print" style={{ position: "sticky", top: 0, zIndex: 5,
        background: "rgba(28,31,34,.95)", backdropFilter: "blur(6px)", padding: "12px 16px",
        display: "flex", gap: 10, justifyContent: "center", alignItems: "center",
        borderBottom: "1px solid " + C.ainezu }}>
        <span style={{ color: "#9aa3ac", fontSize: 12, fontWeight: 700 }}>箇所数プレビュー</span>
        {[1, 2, 3].map((v) => (
          <button key={v} onClick={() => setN(v)} style={{ border: "none", borderRadius: 8,
            padding: "6px 14px", fontSize: 13, fontWeight: 800,
            background: n === v ? C.rust : "rgba(255,255,255,.1)", color: "#fff" }}>{v}箇所</button>
        ))}
      </div>

      {/* A4 縦 */}
      <div style={{ display: "flex", justifyContent: "center", paddingTop: 24 }}>
        <div className="sheet" style={{ width: "100%", maxWidth: 620, aspectRatio: "210 / 297",
          background: C.paper, color: C.ink, borderRadius: 3, boxShadow: "0 16px 44px rgba(0,0,0,.45)",
          display: "flex", flexDirection: "column", overflow: "hidden" }}>

          {/* ヘッダー */}
          <div style={{ display: "flex", alignItems: "stretch", borderBottom: "2px solid " + C.ink }}>
            <div style={{ flex: 1, padding: "12px 18px", display: "flex", alignItems: "center", gap: 12 }}>
              <div style={{ width: 6, alignSelf: "stretch", background: C.rust }} />
              <div>
                <div style={{ fontSize: 9, letterSpacing: ".25em", color: C.kawara, fontWeight: 800 }}>工事写真台帳</div>
                <div style={{ fontSize: 17, fontWeight: 900, lineHeight: 1.15, marginTop: 2 }}>安村様邸　屋根葺き替え工事</div>
              </div>
            </div>
            <div style={{ padding: "12px 18px", display: "flex", alignItems: "center" }}>
              <div style={{ fontSize: 12, fontWeight: 800, color: C.ink }}>有限会社 山西瓦店</div>
            </div>
          </div>

          {/* 3箇所を縦に。番号 / 写真(黄金比の大) / 情報(黄金比の小) */}
          <div style={{ flex: 1, display: "flex", flexDirection: "column", minHeight: 0 }}>
            {rows.map((r, idx) => (
              <div key={r.no} style={{ flex: 1, display: "flex", minHeight: 0, alignItems: "center",
                padding: "10px 16px", gap: 12,
                borderBottom: idx < rows.length - 1 ? "1px solid " + C.line : "none" }}>

                {/* 左：番号バッジ */}
                <div style={{ flex: "0 0 auto", display: "flex", flexDirection: "column", alignItems: "center", width: 40 }}>
                  <span style={{ fontSize: 8, fontWeight: 800, color: C.rust, letterSpacing: ".08em" }}>No.</span>
                  <span style={{ fontSize: 32, fontWeight: 900, color: C.rust, lineHeight: 0.85, letterSpacing: "-.02em" }}>
                    {String(r.no).padStart(2, "0")}
                  </span>
                  <div style={{ width: 20, height: 3, background: C.ink, marginTop: 6 }} />
                </div>

                {/* 写真＋情報を黄金比で。この2つで残り幅を分ける */}
                <div style={{ flex: 1, minWidth: 0, display: "flex", gap: 12, alignItems: "center", alignSelf: "stretch" }}>
                  {/* 写真（黄金比の大 61.8%）。枠を4:3に固定し、写真全体を切れずに収める */}
                  <div style={{ flex: "0 0 " + PHOTO_W, maxWidth: PHOTO_W, aspectRatio: "4 / 3",
                    maxHeight: "88%", position: "relative", overflow: "hidden",
                    background: "#ddd8d0", borderRadius: 2, display: "grid", placeItems: "center",
                    border: "1px solid " + C.line }}>
                    {r.photo ? (
                      <img src={r.photo} alt="" style={{ display: "block", width: "100%", height: "100%", objectFit: "cover" }} />
                    ) : (
                      <div style={{ width: "100%", height: "100%", position: "relative",
                        display: "grid", placeItems: "center" }}>
                        <span style={{ fontSize: 26, color: "rgba(0,0,0,.14)" }}>&#9638;</span>
                        <span style={{ position: "absolute", bottom: 5, fontSize: 8, color: "rgba(0,0,0,.3)" }}>
                          iPhone横向き写真（4:3）
                        </span>
                      </div>
                    )}
                  </div>

                  {/* 情報（黄金比の小 38.2%） */}
                  <div style={{ flex: "1 1 " + INFO_W, minWidth: 0, display: "flex", flexDirection: "column", justifyContent: "center" }}>
                    <div style={{ fontSize: 8, color: C.kawara, fontWeight: 800, letterSpacing: ".1em" }}>工程</div>
                    <div style={{ fontSize: 12.5, fontWeight: 900, lineHeight: 1.25,
                      display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical",
                      overflow: "hidden", wordBreak: "break-word" }}>
                      {r.work}
                    </div>
                    <div style={{ fontSize: 8.5, color: C.kawara, marginTop: 2, lineHeight: 1.3 }}>
                      {r.date}　/　{r.place}
                    </div>

                    {/* 基準値・実測値（ラベル上・数字下で揃える。左端を統一） */}
                    <div style={{ marginTop: 8, display: "flex", gap: 14, alignItems: "flex-end" }}>
                      <div>
                        <div style={{ fontSize: 8, color: C.kawara, fontWeight: 800, letterSpacing: ".1em" }}>基準値</div>
                        <div style={{ fontSize: 15, fontWeight: 900, color: C.steel, lineHeight: 1.05 }}>
                          {r.standard}<span style={{ fontSize: 9 }}>{r.unit}</span>
                          <span style={{ fontSize: 9, color: C.kawara, marginLeft: 2 }}>{r.rule}</span>
                        </div>
                      </div>
                      <div style={{ borderLeft: "3px solid " + C.rust, paddingLeft: 10 }}>
                        <div style={{ fontSize: 8, color: C.rust, fontWeight: 800, letterSpacing: ".1em" }}>実測値</div>
                        <div style={{ fontSize: 24, fontWeight: 900, color: C.ink, lineHeight: 1 }}>
                          {r.actual}<span style={{ fontSize: 11 }}>{r.unit}</span>
                        </div>
                      </div>
                    </div>

                    {/* 所見 */}
                    <div style={{ fontSize: 8.5, color: "#33383d", lineHeight: 1.4, marginTop: 7,
                      paddingLeft: 8, borderLeft: "3px solid " + C.ainezu }}>
                      {r.note}
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {/* フッター */}
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center",
            padding: "7px 18px", background: C.ink, color: "#b9bec4", fontSize: 8.5, letterSpacing: ".08em" }}>
            <span>ナチュラル工房　安村様邸　/　防水ルーフィング工事</span>
            <span>1 / 1</span>
          </div>
        </div>
      </div>

      <p className="no-print" style={{ textAlign: "center", color: "#aeb6bd", fontSize: 12, marginTop: 18, lineHeight: 1.7 }}>
        写真エリアと情報欄を黄金比（約1.618:1 = 62%:38%）で配分。<br />
        写真を黄金比の大きい方に、情報を小さい方に。工程名は1行を維持。
      </p>
    </div>
  );
}
